import{_ as e,o as i,c as a,a0 as n}from"./chunks/framework.C3yZ6M33.js";const k=JSON.parse('{"title":"Run a CI runner fleet","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/ci-runner-fleet.md","filePath":"how-to/ci-runner-fleet.md"}'),t={name:"how-to/ci-runner-fleet.md"};function o(l,s,h,r,p,d){return i(),a("div",null,[...s[0]||(s[0]=[n(`<h1 id="run-a-ci-runner-fleet" tabindex="-1">Run a CI runner fleet <a class="header-anchor" href="#run-a-ci-runner-fleet" aria-label="Permalink to &quot;Run a CI runner fleet&quot;">​</a></h1><p>A <em>fleet</em> is N ephemeral peregrin nodes booted on CI runners, joined to a hub that outlives them. GitHub Actions ships the pieces:</p><ul><li><code>.github/workflows/peregrin-ci.yml</code> — the <strong>reusable workflow</strong> any repo can call for a single CI node or a local campaign run.</li><li><code>.github/workflows/ephemeral-fleet.yml</code> — a <code>workflow_dispatch</code><strong>example</strong> that boots a matrix of runners as nodes.</li><li><code>.github/actions/install-peregrin</code> — the shared install step (release binary when published, <code>cargo install --git</code> until then).</li></ul><h2 id="topology-—-read-this-first" tabindex="-1">Topology — read this first <a class="header-anchor" href="#topology-—-read-this-first" aria-label="Permalink to &quot;Topology — read this first&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        hub (your machine / server / long-lived runner)</span></span>
<span class="line"><span>         │  PEREGRIN_NODES=&quot;ci-1=http://…:18787@tok;ci-2=…&quot;</span></span>
<span class="line"><span>         │  ▲ hub→node ops only work if the hub can REACH the node</span></span>
<span class="line"><span>         │</span></span>
<span class="line"><span>   ┌─────┴──────────────────────────┐</span></span>
<span class="line"><span>   │  runner ci-1   runner ci-2 …   │   GitHub-hosted: NO inbound</span></span>
<span class="line"><span>   │  peregrin serve --ephemeral    │   connections — hub cannot dial</span></span>
<span class="line"><span>   └─────┬──────────────────────────┘   them; useful directions are</span></span>
<span class="line"><span>         │ outbound: snapshots → hub,  │   OUTBOUND only:</span></span>
<span class="line"><span>         │ \`peregrin\` CLI → hub/node   │</span></span></code></pre></div><ul><li><strong>Hub stays home.</strong> It owns the entity plane view, the lock book, and the outbox. Ephemeral runners join it as ordinary nodes — auth is config (<code>PEREGRIN_NODES=id=url[@token];…</code> on the hub, <code>PEREGRIN_TOKEN</code> on each node), never pairing.</li><li><strong>Runners are ephemeral nodes.</strong> On SIGTERM each flushes snapshots of <code>live</code>/<code>locked</code> entities — locally under <code>PEREGRIN_SNAPSHOT_DIR</code> (uploaded as a job artifact) and/or handed off to <code>PEREGRIN_SNAPSHOT_TARGET</code> so the entity resumes where it can keep running.</li><li><strong>Ops route via ownership.</strong> The hub arbitrates locks (<code>hypha-control</code>, ~30s stale threshold) and forwards ops to the node that owns an entity — <em>if it can reach it</em>. On GitHub-hosted runners that means outbound-only: snapshots and client verbs. For real hub→runner op routing use <strong>self-hosted runners on a tailnet/LAN</strong> the hub can dial.</li></ul><h2 id="single-job-—-the-reusable-workflow" tabindex="-1">Single job — the reusable workflow <a class="header-anchor" href="#single-job-—-the-reusable-workflow" aria-label="Permalink to &quot;Single job — the reusable workflow&quot;">​</a></h2><p>Any repo calls it; the workflow checks out <em>your</em> repo, installs peregrin, and runs one of two modes:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">jobs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  campaign</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    uses</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">9aia/peregrin/.github/workflows/peregrin-ci.yml@main</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    with</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">campaign-run</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      campaign</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">path/to/campaign.yaml</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      campaign-args</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">--dry-run</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  node</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    uses</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">9aia/peregrin/.github/workflows/peregrin-ci.yml@main</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    with</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ephemeral-node</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      command</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">peregrin sessions list</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # any shell; node env is set</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      node-id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ci-worker</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # stable id for PEREGRIN_NODES</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      snapshot-target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://hub.tailnet:13000</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      snapshot-node</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">home-node</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # hub-side import target</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    secrets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      PEREGRIN_TOKEN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${{ secrets.PEREGRIN_TOKEN }}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      PEREGRIN_SNAPSHOT_TOKEN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${{ secrets.PEREGRIN_SNAPSHOT_TOKEN }}</span></span></code></pre></div><p><code>ephemeral-node</code> boots <code>peregrin serve --ephemeral</code> on <code>127.0.0.1:$port</code>, waits for <code>/api/health</code>, runs <code>command</code> (with <code>PEREGRIN_NODE_URL</code>/<code>PEREGRIN_TOKEN</code> in env), then SIGTERMs — the flush runs even when <code>command</code> fails (<code>if: always()</code>). Snapshots are uploaded as a <code>peregrin-snapshots-*</code> artifact.</p><p>Secrets are never echoed: <code>PEREGRIN_TOKEN</code>, <code>PEREGRIN_SNAPSHOT_TOKEN</code>, <code>HYPHA_OTEL_ENDPOINT</code>, <code>HYPHA_OTEL_SERVICE_NAME</code>. See the header comment in <code>peregrin-ci.yml</code> for the full input list.</p><h2 id="the-fleet-example" tabindex="-1">The fleet example <a class="header-anchor" href="#the-fleet-example" aria-label="Permalink to &quot;The fleet example&quot;">​</a></h2><p><code>.github/workflows/ephemeral-fleet.yml</code> is <code>workflow_dispatch</code>-only — dispatch it from the Actions tab:</p><table tabindex="0"><thead><tr><th>input</th><th>meaning</th></tr></thead><tbody><tr><td><code>nodes</code></td><td>JSON array of node ids — <code>[&quot;ci-1&quot;,&quot;ci-2&quot;]</code>. Each becomes the seeded <code>node.json</code> id the hub&#39;s <code>PEREGRIN_NODES</code> names.</td></tr><tr><td><code>hub-url</code></td><td>Snapshot handoff target <strong>and</strong> the URL <code>peregrin</code> CLI verbs use.</td></tr><tr><td><code>snapshot-node</code></td><td>Which registered node the hub imports snapshots onto (required for hub handoff — the hub stores no snapshots itself).</td></tr><tr><td><code>hold-seconds</code></td><td>How long nodes stay up.</td></tr><tr><td><code>peregrin-ref</code></td><td>Git ref to install (branch/tag/SHA).</td></tr></tbody></table><p>Repo secrets: <code>PEREGRIN_TOKEN</code> (one shared bearer — every node accepts it and the hub presents it), <code>PEREGRIN_SNAPSHOT_TOKEN</code> (what the handoff target expects; falls back to <code>PEREGRIN_TOKEN</code>), optional <code>PEREGRIN_HUB_TOKEN</code>. Optional var <code>PEREGRIN_FLEET_HOST</code> overrides the <code>0.0.0.0</code> bind.</p><p>Each matrix leg seeds <code>$PEREGRIN_HOME/node.json</code> with its matrix id <strong>before first boot</strong>, so the hub can list <code>ci-1=http://…@tok</code> in <code>PEREGRIN_NODES</code> instead of chasing auto-minted <code>node_&lt;hex&gt;</code> ids.</p><h2 id="installing-peregrin-on-the-runner" tabindex="-1">Installing peregrin on the runner <a class="header-anchor" href="#installing-peregrin-on-the-runner" aria-label="Permalink to &quot;Installing peregrin on the runner&quot;">​</a></h2><p>Until published releases exist (tracked as T-003), the install step runs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> url.&quot;https://github.com/&quot;.insteadOf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ssh://git@github.com/&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/9aia/peregrin.git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> peregrin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --branch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">re</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">f</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Two things to know:</p><ul><li><strong>The ssh→https rewrite is required.</strong> peregrin&#39;s manifest pins <code>sepia</code>/<code>tamias</code>/<code>hypha</code> crates as <code>ssh://git@github.com/…</code> deps; runners have no SSH keys. The repos are public, so https works.</li><li><strong>It compiles the dependency graph</strong> — expect several minutes on a cold cache (<code>Swatinem/rust-cache</code> helps across runs). Once T-003 ships release tarballs, the same step downloads <code>peregrin-x86_64-unknown-linux-gnu.tar.gz</code> instead — no workflow change needed.</li></ul><h2 id="session-plane-honesty" tabindex="-1">Session plane honesty <a class="header-anchor" href="#session-plane-honesty" aria-label="Permalink to &quot;Session plane honesty&quot;">​</a></h2><p><code>PEREGRIN_SESSION_PLANE=local</code> (the default in both workflows) links <code>sepia-session</code> <strong>in-process</strong> — the node boots with only the <code>peregrin</code> binary, no <code>sepia</code> install. Campaign and substrate work (<code>kind=&quot;campaign&quot;</code>, entities, ops, snapshots) needs nothing more. Real agent sessions still need the sepia <strong>drivers</strong> (<code>sepia-driver-*</code> on <code>PATH</code>) and, if you unset the plane override, the <code>sepia</code> binary itself (<code>PEREGRIN_SEPIA</code> or PATH).</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./run-a-ci-node.html">Run a CI runner node</a> — the single-node mechanics (env vars, snapshot destinations, locks).</li><li><a href="./run-a-hub.html">Run a hub</a> — <code>PEREGRIN_NODES</code> config on the hub side.</li></ul>`,25)])])}const g=e(t,[["render",o]]);export{k as __pageData,g as default};
